from pathlib import Path
from bs4 import BeautifulSoup
import re,json,hashlib,sys
wd=Path('.'); idx=(wd/'index.html').read_text(); app=(wd/'app.js').read_text(); man=(wd/'manifest.webmanifest').read_text(); sw=(wd/'sw.js').read_text(); checks=[]
