soup=BeautifulSoup(idx,'html.parser'); ids=[x.get('id') for x in soup.find_all(attrs={'id':True})]; refs=set(re.findall(r'(?:\$|must)\(["\']([A-Za-z0-9_:-]+)["\']\)',app)); refs.update(re.findall(r'document\.getElementById\(["\']([A-Za-z0-9_:-]+)["\']\)',app)); missing=sorted(refs-set(ids)); m=re.search(r'<script>\n(.*?)\n</script>\n</body>',idx,re.S)
chk('HTML parsed',soup.html is not None); chk('unique IDs',len(ids)==len(set(ids)),f'{len(ids)}'); chk('DOM refs',not missing,str(missing[:8])); chk('inline/app byte-equivalent',bool(m and m.group(1)==app.rstrip('\n')))
